try:
    import socket
    import binascii
    import time
    import queue
    import binascii
    import os
    import logging
    import sys
except:
    os._exit(6)
logging.basicConfig(level=logging.INFO,format='%(message)s')


def check(ip,port):
    datas = [b'/Simple!addInput.action',b'/Simple.action',b'/addUser.action',b'/listUser.action',b'/helloworld.action',b'/example/HelloWorld.action']
    data1 = b"504f535420"
    data2 = b""
    for data in datas:
        s = socket.socket(socket.AF_INET,socket.SOCK_STREAM)
        s.settimeout(5)
        try:
            s.connect((ip,port))
        except Exception as e:
            os._exit(4)

        s.send(binascii.a2b_hex(data1)+data+binascii.a2b_hex(data2))
        time.sleep(1)
        get = s.recv(4096)
        s.close()
        if ("uid" in get):
            logging.info( '[+] Found S2-005 in ' + ip + ':' + str(port))
            os._exit(1)
        
    logging.info('[-] S2-005 Not Found in ' + ip + ':' + str(port))
    os._exit(2)

if __name__ == "__main__":

    ip = sys.argv[1]
    port = sys.argv[2]
    check(ip,int(port))